export interface ReturnParameterMembership extends ParameterMembership {
    readonly $container: AcceptActionUsage | AnnotatingElement | AssignmentActionUsage | Connector | Dependency | Expression | Feature | FeatureReferenceExpression | FlowConnectionUsage | ForLoopActionUsage | IfActionUsage | InvocationExpression | ItemFlow | MultiplicityRange | Namespace | Relationship | SatisfyRequirementUsage | SendActionUsage | SysMLFunction | TerminateActionUsage | TransitionUsage | Type | WhileLoopActionUsage;
    readonly $type: 'ReturnParameterMembership';
}

export interface FeatureReferenceExpression extends Expression {
    readonly $container: AcceptActionUsage | AnnotatingElement | AssignmentActionUsage | Connector | Dependency | Expression | Feature | FeatureReferenceExpression | FlowConnectionUsage | ForLoopActionUsage | IfActionUsage | InvocationExpression | ItemFlow | MultiplicityRange | Namespace | Relationship | SatisfyRequirementUsage | SendActionUsage | SysMLFunction | TerminateActionUsage | TransitionUsage | Type | WhileLoopActionUsage;
    readonly $type: 'FeatureReferenceExpression';
    expression: Membership
}

export const FeatureReferenceExpression = 'FeatureReferenceExpression';

export function isFeatureReferenceExpression(item: unknown): item is FeatureReferenceExpression {
    return reflection.isInstance(item, FeatureReferenceExpression);
}

export interface InvocationExpression extends Expression {
    readonly $container: AcceptActionUsage | AnnotatingElement | AssignmentActionUsage | Connector | Dependency | Expression | Feature | FeatureReferenceExpression | FlowConnectionUsage | ForLoopActionUsage | IfActionUsage | InvocationExpression | ItemFlow | MultiplicityRange | Namespace | Relationship | SatisfyRequirementUsage | SendActionUsage | SysMLFunction | TerminateActionUsage | TransitionUsage | Type | WhileLoopActionUsage;
    readonly $type: 'CollectExpression' | 'FeatureChainExpression' | 'IndexExpression' | 'InvocationExpression' | 'OperatorExpression' | 'SelectExpression' | 'TriggerInvocationExpression';
    operands: Array<Expression>
}

export interface OperatorExpression extends InvocationExpression {
    readonly $container: AcceptActionUsage | AnnotatingElement | AssignmentActionUsage | Connector | Dependency | Expression | Feature | FeatureReferenceExpression | FlowConnectionUsage | ForLoopActionUsage | IfActionUsage | InvocationExpression | ItemFlow | MultiplicityRange | Namespace | Relationship | SatisfyRequirementUsage | SendActionUsage | SysMLFunction | TerminateActionUsage | TransitionUsage | Type | WhileLoopActionUsage;
    readonly $type: 'CollectExpression' | 'FeatureChainExpression' | 'IndexExpression' | 'OperatorExpression' | 'SelectExpression';
    operator?: string
}

const ClassificationTestOperator = ["istype", "hastype", "@", "as"];

/**
 * The grammar rules that calls `SelfReferenceExpression` rule breaks parsing
 * with Langium, resolve it here.
 */
function fixOperatorExpression(expr: OperatorExpression, services: SysMLDefaultServices): void {
    if (!expr.operands) expr.operands = [];
    if (
        expr.operands.length === 0 &&
        expr.operator &&
        ClassificationTestOperator.includes(expr.operator)
    ) {
        const reflection = services.shared.AstReflection;
        const expression = reflection.createNode(FeatureReferenceExpression, {
            $container: expr,
            $containerProperty: "operands",
            $containerIndex: 0,
        });

        const member = reflection.createNode(ReturnParameterMembership, {
            $container: expression,
            $containerProperty: "expression",
        });

        reflection.createNode(Feature, {
            $container: member,
            $containerProperty: "target",
        });
    }
}

    // map to postprocess specific AST node types after parsing
    const map: ProcessingMap = {
        OperatorExpression: fixOperatorExpression,
        WhileLoopActionUsage: addLoopMember,
        Import: finalizeImport,
        TransitionUsage: createEmptyParametersInTransitionUsage,
        SuccessionAsUsage: createMissingEndsInSuccessionAsUsage,
    };

    this.postprocessingMap = typeIndex.expandToDerivedTypes(
        map as TypeMap<SysMLTypeList, ProcessingFunction>
    );
}

override construct(item: { $type: string | symbol | undefined; $cstNode: CstNode }): void {
    super.construct(item);
    if (typeof item.$type === "string") {
        this.postprocessingMap.get(item.$type)?.call(undefined, item as AstNode, this.services);
    }

createNode<
    V extends SysMLType,
    T extends AstParent<SysMLInterface<V>>,
    P extends AstPropertiesFor<SysMLInterface<V>, T>,
>(type: V, values: ConstructParams<SysMLInterface<V>, T, P>): SysMLInterface<V> {
    const partialNode = { $type: type, ...values };

    // if there's a CST node, modify it to point to the created node
    if (values.$cstNode) {
        const cstNode = shallowClone(values.$cstNode);
        (cstNode as Mutable<CstNode>).element = partialNode as AstNode;
        (partialNode as Mutable<AstNode>).$cstNode = cstNode;
        (cstNode as AutoCstNode).$implicit = true;
    }
    this.assignMandatoryProperties(partialNode);
    return this.assignNode(partialNode as unknown as SysMLInterface<V>, values);
}

/**
 * Assign {@link child} to a parent AST node with {@link info}
 * @param child Child AST node
 * @param info Properties defining {@link child} parent and its relationship
 * @returns child
 */
assignNode<V extends AstNode, T extends AstParent<V>, P extends AstPropertiesFor<V, T>>(
    child: V,
    info: AstContainer<V, T, P>
): V {
    const parent = info.$container;
    const property = info.$containerProperty;
    if (!parent || !property) return child;
    const member = (parent as NonNullable<T>)[property];
    const index = info.$containerIndex;
    if (Array.isArray(member)) {
        const array = member as AstNode[];
        if (index !== undefined) {
            array.forEach((v, i) => {
                if (i >= index) (v as Mutable<AstNode>).$containerIndex = i + 1;
            });
            array.splice(index, 0, child);
            (child as Mutable<AstNode>).$containerIndex = index;
        } else {
            array.push(child);
            (child as Mutable<AstNode>).$containerIndex = array.length - 1;
        }
    } else {
        if (index !== undefined)
            throw new Error("Cannot assign with an index to a non-array property");
        (parent as unknown as Record<string, V>)[property as string] = child;
    }

    (child as Mutable<AstNode>).$container = parent;
    (child as Mutable<AstNode>).$containerProperty = property as string;

    // if this was called during parsing, it may be possible that $children
    // has not been created yet
    if (parent.$children) {
        const cst = child.$cstNode;
        if (cst) {
            const index = parent.$children.findIndex((node) => {
                if (!node.$cstNode) return;
                return node.$cstNode.offset > cst.end;
            });
            if (index >= 0) {
                parent.$children
                    .slice(index)
                    .forEach((node) => (node as Mutable<AstNode>).$childIndex++);
                parent.$children.splice(index, 0, child);
            }
        }
        parent.$children.push(child);
        (child as Mutable<AstNode>).$childIndex = parent.$children.length - 1;
    }
    return child;
